### 3. CODIFICAÇÃO EM JAVA

```java
import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;

public class Main {

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class Node {
        long ans;
        // Pares (gcd, count) para prefixos
        int prefSz;
        int[] prefGcd = new int[32];
        int[] prefCnt = new int[32];

        // Pares (gcd, count) para sufixos
        int suffSz;
        int[] suffGcd = new int[32];
        int[] suffCnt = new int[32];

        int totalGcd;

        void setLeaf(int val) {
            ans = (val > 1) ? 1 : 0;
            totalGcd = val;
            prefSz = 1;
            prefGcd[0] = val;
            prefCnt[0] = 1;

            suffSz = 1;
            suffGcd[0] = val;
            suffCnt[0] = 1;
        }
    }

    static Node merge(Node L, Node R, Node res) {
        if (L == null) return R;
        if (R == null) return L;

        long cross = 0;
        // Combinações de sufixo de L com prefixo de R
        for (int i = 0; i < L.suffSz; i++) {
            int g1 = L.suffGcd[i];
            if (g1 <= 1) continue;
            long c1 = L.suffCnt[i];

            for (int j = 0; j < R.prefSz; j++) {
                int g = gcd(g1, R.prefGcd[j]);
                if (g > 1) {
                    cross += c1 * R.prefCnt[j];
                } else {
                    // Como os prefixos seguintes de R dividem R.prefGcd[j],
                    // o gcd com g1 também será 1. Poda imediata!
                    break;
                }
            }
        }

        res.ans = L.ans + R.ans + cross;
        res.totalGcd = gcd(L.totalGcd, R.totalGcd);

        // Construir prefixos do nó combinado
        res.prefSz = 0;
        for (int i = 0; i < L.prefSz; i++) {
            res.prefGcd[res.prefSz] = L.prefGcd[i];
            res.prefCnt[res.prefSz] = L.prefCnt[i];
            res.prefSz++;
        }
        for (int i = 0; i < R.prefSz; i++) {
            int g = gcd(L.totalGcd, R.prefGcd[i]);
            if (res.prefGcd[res.prefSz - 1] == g) {
                res.prefCnt[res.prefSz - 1] += R.prefCnt[i];
            } else {
                res.prefGcd[res.prefSz] = g;
                res.prefCnt[res.prefSz] = R.prefCnt[i];
                res.prefSz++;
            }
        }

        // Construir sufixos do nó combinado
        res.suffSz = 0;
        for (int i = 0; i < R.suffSz; i++) {
            res.suffGcd[res.suffSz] = R.suffGcd[i];
            res.suffCnt[res.suffSz] = R.suffCnt[i];
            res.suffSz++;
        }
        for (int i = 0; i < L.suffSz; i++) {
            int g = gcd(R.totalGcd, L.suffGcd[i]);
            if (res.suffGcd[res.suffSz - 1] == g) {
                res.suffCnt[res.suffSz - 1] += L.suffCnt[i];
            } else {
                res.suffGcd[res.suffSz] = g;
                res.suffCnt[res.suffSz] = L.suffCnt[i];
                res.suffSz++;
            }
        }

        return res;
    }

    static int N, M;
    static int[] S;
    static Node[] tree;

    static void build(int node, int l, int r) {
        tree[node] = new Node();
        if (l == r) {
            tree[node].setLeaf(S[l]);
            return;
        }
        int mid = (l + r) >> 1;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        merge(tree[2 * node], tree[2 * node + 1], tree[node]);
    }

    static void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            tree[node].setLeaf(val);
            return;
        }
        int mid = (l + r) >> 1;
        if (idx <= mid) {
            update(2 * node, l, mid, idx, val);
        } else {
            update(2 * node + 1, mid + 1, r, idx, val);
        }
        merge(tree[2 * node], tree[2 * node + 1], tree[node]);
    }

    static Node query(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            return tree[node];
        }
        int mid = (l + r) >> 1;
        if (qr <= mid) {
            return query(2 * node, l, mid, ql, qr);
        }
        if (ql > mid) {
            return query(2 * node + 1, mid + 1, r, ql, qr);
        }
        Node leftRes = query(2 * node, l, mid, ql, qr);
        Node rightRes = query(2 * node + 1, mid + 1, r, ql, qr);
        Node res = new Node();
        return merge(leftRes, rightRes, res);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        N = fs.nextInt();
        M = fs.nextInt();

        S = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            S[i] = fs.nextInt();
        }

        tree = new Node[4 * N + 1];
        build(1, 1, N);

        for (int i = 0; i < M; i++) {
            int type = fs.nextInt();
            if (type == 1) {
                int pos = fs.nextInt();
                int val = fs.nextInt();
                update(1, 1, N, pos, val);
            } else {
                int l = fs.nextInt();
                int r = fs.nextInt();
                Node res = query(1, 1, N, l, r);
                out.println(res.ans);
            }
        }

        out.flush();
    }

    // Leitor de alta performance para lidar com E/S de 10^5 elementos
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                buflen = -1;
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) c = readByte();
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res;
        }
    }
}
```

